using Microsoft.Win32;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using ToneCustoms.ShellStudio.Bridges;using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Editor;using ToneCustoms.ShellStudio.Export;using ToneCustoms.ShellStudio.Validation;
namespace ToneCustoms.ShellStudio;
public partial class MainWindow:Window { readonly EditorSession editor=new();readonly GeometryService geometry=new();readonly ProjectService projects=new();readonly ProjectValidator validator=new();readonly PerformanceAnalyzer performance=new();readonly ToolchainService toolchain=new();readonly AutosaveController autosave;string? projectPath;public MainWindow(){InitializeComponent();ProjectPaths.Ensure();autosave=new(projects,()=>editor.Project);Closed+=(_,_)=>autosave.Dispose();editor.Changed+=Refresh;Refresh();}void Refresh(){SceneList.ItemsSource=null;SceneList.ItemsSource=editor.Project.Objects;SelectedName.Text=editor.Selected?.Name??"Nothing selected";if(editor.Selected is{} o){PositionBox.Text=V(o.Position);RotationBox.Text=V(o.Rotation);ScaleBox.Text=V(o.Scale);}var p=performance.Analyze(editor.Project);PerformanceText.Text=$"Objects: {p.Objects} • Collision: {p.CollisionObjects} • Materials: {p.Materials} • {p.Rating}";StatusText.Text=$"Ready • {(editor.Project.Settings.AdvancedMode?"Advanced":"Simple")} Mode • Project: {editor.Project.Name}";}static string V(Vec3 v)=>$"{v.X:0.###}, {v.Y:0.###}, {v.Z:0.###}";static Vec3 Parse(string s){var a=s.Split(',').Select(x=>float.Parse(x.Trim(),CultureInfo.InvariantCulture)).ToArray();if(a.Length!=3)throw new FormatException("Enter X, Y, Z");return new(a[0],a[1],a[2]);}void New_Click(object s,RoutedEventArgs e){editor.NewProject("Untitled");projectPath=null;}async void Open_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="ToneCustoms Shell (*.tcshell)|*.tcshell"};if(d.ShowDialog()==true){editor.LoadProject(await projects.LoadAsync(d.FileName));projectPath=d.FileName;}}async void Save_Click(object s,RoutedEventArgs e){if(projectPath==null){var d=new SaveFileDialog{Filter="ToneCustoms Shell (*.tcshell)|*.tcshell",FileName=editor.Project.Name+".tcshell",InitialDirectory=ProjectPaths.Projects};if(d.ShowDialog()!=true)return;projectPath=d.FileName;}await projects.SaveAsync(editor.Project,projectPath);await projects.SnapshotAsync(editor.Project,ProjectPaths.AppRoot);StatusText.Text="Project saved • snapshot created";}void AddObject_Click(object s,RoutedEventArgs e){var tag=(s as Button)?.Tag?.ToString();var p=new Vec3();SceneObject o=tag switch{"Wall"=>geometry.Wall(p),"Room"=>geometry.Room(p),"Floor"=>geometry.Floor(p),"Ceiling"=>geometry.Ceiling(new(0,0,3)),"Door"=>geometry.Door(p),"Window"=>geometry.Window(new(0,0,1)),"Stairs"=>geometry.Stairs(p),_=>geometry.Wall(p)};editor.Add(o);}void SceneList_SelectionChanged(object s,SelectionChangedEventArgs e){if(SceneList.SelectedItem is SceneObject o)editor.Select(o.Id);}void ApplyTransform_Click(object s,RoutedEventArgs e){if(editor.Selected==null)return;try{editor.BeforeMutation();var p=Parse(PositionBox.Text);if(SnapCheck.IsChecked==true)p=geometry.Snap(p,editor.Project.Settings.GridSize);editor.Selected.Position=p;editor.Selected.Rotation=Parse(RotationBox.Text);editor.Selected.Scale=Parse(ScaleBox.Text);Refresh();}catch(Exception ex){MessageBox.Show(ex.Message,"Transform");}}void Delete_Click(object s,RoutedEventArgs e)=>editor.DeleteSelected();void Duplicate_Click(object s,RoutedEventArgs e)=>editor.DuplicateSelected();void Undo_Click(object s,RoutedEventArgs e){if(!editor.Undo())StatusText.Text="Nothing to undo";}void Move_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Move;ViewportInfo.Text="MOVE • XYZ gizmo mode";}void Rotate_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Rotate;ViewportInfo.Text="ROTATE • XYZ gizmo mode";}void Scale_Click(object s,RoutedEventArgs e){editor.Mode=TransformMode.Scale;ViewportInfo.Text="SCALE • XYZ gizmo mode";}void Validate_Click(object s,RoutedEventArgs e){var i=validator.Validate(editor.Project);ValidationText.Text=i.Count==0?"PASS — no project-model errors":string.Join("\n",i.Select(x=>$"{x.Severity}: {x.Area} — {x.Message}"));}void AutoFix_Click(object s,RoutedEventArgs e){editor.BeforeMutation();validator.AutoFixSafe(editor.Project);Validate_Click(s,e);Refresh();}void Dependencies_Click(object s,RoutedEventArgs e){var t=toolchain.Status();MessageBox.Show(string.Join("\n",t.Select(x=>$"{x.Name}: {(x.Found?"FOUND":"NOT FOUND")} {x.Path}")),"Shell Studio Toolchain");}void Mode_Click(object s,RoutedEventArgs e){editor.Project.Settings.AdvancedMode=!editor.Project.Settings.AdvancedMode;Refresh();}void Test_Click(object s,RoutedEventArgs e)=>ViewportInfo.Text="WALK PREVIEW • player-height/collision preview mode";void Export_Click(object s,RoutedEventArgs e){var readiness=new ExportReadinessService().Check(editor.Project,toolchain.Status());if(readiness.Count>0){MessageBox.Show(string.Join("\n",readiness),"Final GTA export not ready");return;}using var d=new System.Windows.Forms.FolderBrowserDialog();if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;var r=new ExportPipeline().Prepare(editor.Project,d.SelectedPath);if(!r.Success){MessageBox.Show(string.Join("\n",r.Issues.Select(x=>x.Message)),"Export blocked");return;}MessageBox.Show("FiveM resource staging prepared at:\n"+r.ResourcePath+"\n\nShell Studio will only treat this as final after Blender/Sollumz conversion output is verified.","Shell Studio Export");}void Materials_Click(object s,RoutedEventArgs e)=>MessageBox.Show("DDS-first material subsystem loaded.");void Props_Click(object s,RoutedEventArgs e)=>MessageBox.Show("GTA/custom prop catalog subsystem loaded.");void Import_Click(object s,RoutedEventArgs e)=>MessageBox.Show("Model import subsystem loaded.");void Window_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.F5)Test_Click(s,new RoutedEventArgs());if(e.Key==Key.W)Move_Click(s,new RoutedEventArgs());if(e.Key==Key.E)Rotate_Click(s,new RoutedEventArgs());if(e.Key==Key.R)Scale_Click(s,new RoutedEventArgs());if(e.Key==Key.Delete)Delete_Click(s,new RoutedEventArgs());if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Z)editor.Undo();if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Y)editor.Redo();}}
